// (setTimeout) so every microtask from that handler — including onMutate's internal
// await — is guaranteed to have fully drained, exactly as the browser guarantees
// between two separate click events.
function nextTask() {
  return new Promise((resolve) => setTimeout(resolve, 0));
}

