// Minimal stand-in for @tanstack/react-query's cache surface, enough to exercise
// the exact onMutate/onSuccess/onError + sequence-guard logic in todoist-context.tsx.
class FakeQueryClient {
  constructor() { this.store = new Map(); }
  key(k) { return JSON.stringify(k); }
  getQueryData(k) { return this.store.get(this.key(k)); }
  setQueryData(k, v) { this.store.set(this.key(k), v); }
  removeQueries({ queryKey }) { this.store.delete(this.key(queryKey)); }
  invalidateQueries() { this.invalidated = (this.invalidated ?? 0) + 1; return Promise.resolve(); }
  async cancelQueries() { await Promise.resolve(); }
}

const getGetTodoistSettingsQueryKey = () => ["getTodoistSettings"];

// Exact port of TodoistProvider's mutation config: same onMutate/onSuccess/onError
// bodies, same latestSequenceRef closure semantics (via a plain object standing in
// for useRef, since refs are just a mutable box across renders).
function makeUpdateSettings(queryClient, latestSequenceRef) {
  return {
    async mutate({ data }, { resolveNetwork }) {
      const queryKey = getGetTodoistSettingsQueryKey();
      // ---- onMutate ----
      const sequence = ++latestSequenceRef.current;
      await queryClient.cancelQueries({ queryKey, exact: true });
      const previous = queryClient.getQueryData(queryKey);
      queryClient.setQueryData(queryKey, data);
      const context = { previous, sequence };

      const outcome = await resolveNetwork;

      if (outcome.ok) {
        // ---- onSuccess ----
        if (!context || context.sequence !== latestSequenceRef.current) {
          return { sentBody: data, context, applied: false, outcome };
        }
        queryClient.setQueryData(queryKey, outcome.serverData);
        return { sentBody: data, context, applied: true, outcome };
      } else {
        // ---- onError ----
        if (!context || context.sequence !== latestSequenceRef.current) {
          return { sentBody: data, context, applied: false, outcome };
        }
        if (context.previous !== undefined) {
          queryClient.setQueryData(queryKey, context.previous);
        } else {
          await queryClient.invalidateQueries({ queryKey, exact: true });
        }
        return { sentBody: data, context, applied: true, outcome };
      }
    },
  };
}

function saveSettings(queryClient, updateSettings, overrides, resolveNetwork) {
  const queryKey = getGetTodoistSettingsQueryKey();
  const current = queryClient.getQueryData(queryKey) ?? { taskProjectId: null, eblastProjectId: null };
  const next = { ...current, ...overrides };
  return updateSettings.mutate({ data: next }, { resolveNetwork });
}

function nextTask() {
  return new Promise((resolve) => setTimeout(resolve, 0));
}

function assert(label, pass) {
  console.log(`${pass ? "PASS" : "FAIL"}  ${label}`);
  if (!pass) process.exitCode = 1;
}

async function scenarioA() {
  console.log("\n=== A. Rapid sequential updates ===");
  const qc = new FakeQueryClient();
  const seqRef = { current: 0 };
  qc.setQueryData(["getTodoistSettings"], { taskProjectId: "A", eblastProjectId: "B" });
  const updateSettings = makeUpdateSettings(qc, seqRef);

  let resolve1; const net1 = new Promise((r) => { resolve1 = r; });
  const req1 = saveSettings(qc, updateSettings, { taskProjectId: "C" }, net1);
  await nextTask();
  console.log("cache after click 1 (network pending):", qc.getQueryData(["getTodoistSettings"]));

  let resolve2; const net2 = new Promise((r) => { resolve2 = r; });
  const req2 = saveSettings(qc, updateSettings, { eblastProjectId: "D" }, net2);
  await nextTask();

  resolve2({ ok: true, serverData: { taskProjectId: "C", eblastProjectId: "D" } });
  const r2 = await req2;
  assert("request 2 body === { C, D }", JSON.stringify(r2.sentBody) === JSON.stringify({ taskProjectId: "C", eblastProjectId: "D" }));

  resolve1({ ok: true, serverData: { taskProjectId: "C", eblastProjectId: "B" } });
  await req1;
}

async function scenarioB() {
  console.log("\n=== B. Out-of-order successful responses ===");
  const qc = new FakeQueryClient();
  const seqRef = { current: 0 };
  qc.setQueryData(["getTodoistSettings"], { taskProjectId: "A", eblastProjectId: "B" });
  const updateSettings = makeUpdateSettings(qc, seqRef);

  let resolve1; const net1 = new Promise((r) => { resolve1 = r; });
  const req1 = saveSettings(qc, updateSettings, { taskProjectId: "C" }, net1); // seq 1, sends {C,B}
  await nextTask();

  let resolve2; const net2 = new Promise((r) => { resolve2 = r; });
  const req2 = saveSettings(qc, updateSettings, { eblastProjectId: "D" }, net2); // seq 2, sends {C,D}
  await nextTask();

  // Request 2 resolves FIRST (its response happens to win the race).
  resolve2({ ok: true, serverData: { taskProjectId: "C", eblastProjectId: "D" } });
  const r2 = await req2;
  console.log("cache after request 2 resolves:", qc.getQueryData(["getTodoistSettings"]));

  // Request 1 resolves LATE — its own (now-stale) view of the world.
  resolve1({ ok: true, serverData: { taskProjectId: "C", eblastProjectId: "B" } });
  const r1 = await req1;
  console.log("request 1 applied to cache?", r1.applied, " (expected: false — it's stale)");
  console.log("final cache:", qc.getQueryData(["getTodoistSettings"]));

  assert("request 1's stale response did NOT apply", r1.applied === false);
  assert("final cache remains { C, D }, not { C, B }", JSON.stringify(qc.getQueryData(["getTodoistSettings"])) === JSON.stringify({ taskProjectId: "C", eblastProjectId: "D" }));
}

async function scenarioC() {
  console.log("\n=== C. Older failure after newer mutation starts ===");
  const qc = new FakeQueryClient();
  const seqRef = { current: 0 };
  qc.setQueryData(["getTodoistSettings"], { taskProjectId: "A", eblastProjectId: "B" });
  const updateSettings = makeUpdateSettings(qc, seqRef);

  let resolve1; const net1 = new Promise((r) => { resolve1 = r; });
  const req1 = saveSettings(qc, updateSettings, { taskProjectId: "C" }, net1); // seq 1 -> optimistic {C,B}
  await nextTask();
  console.log("cache after mutation 1's optimistic write:", qc.getQueryData(["getTodoistSettings"]));

  let resolve2; const net2 = new Promise((r) => { resolve2 = r; });
  const req2 = saveSettings(qc, updateSettings, { eblastProjectId: "D" }, net2); // seq 2 -> optimistic {C,D}
  await nextTask();
  console.log("cache after mutation 2's optimistic write:", qc.getQueryData(["getTodoistSettings"]));

  // Mutation 1 FAILS after mutation 2 has already started.
  resolve1({ ok: false });
  const r1 = await req1;
  console.log("mutation 1's error handler applied a rollback?", r1.applied, " (expected: false — it's stale)");
  console.log("cache after mutation 1's failure:", qc.getQueryData(["getTodoistSettings"]));

  assert("mutation 1's stale failure did NOT roll back", r1.applied === false);
  assert("cache remains { C, D }, not rolled back to { A, B }", JSON.stringify(qc.getQueryData(["getTodoistSettings"])) === JSON.stringify({ taskProjectId: "C", eblastProjectId: "D" }));

  resolve2({ ok: true, serverData: { taskProjectId: "C", eblastProjectId: "D" } });
  await req2;
}

async function scenarioD_withKnownPrevious() {
  console.log("\n=== D. Latest mutation failure (previous state known) ===");
  const qc = new FakeQueryClient();
  const seqRef = { current: 0 };
  qc.setQueryData(["getTodoistSettings"], { taskProjectId: "A", eblastProjectId: "B" });
  const updateSettings = makeUpdateSettings(qc, seqRef);

  let resolve1; const net1 = new Promise((r) => { resolve1 = r; });
  const req1 = saveSettings(qc, updateSettings, { taskProjectId: "C" }, net1);
  await nextTask();
  console.log("cache right after onMutate (optimistic):", qc.getQueryData(["getTodoistSettings"]));

  resolve1({ ok: false });
  const r1 = await req1;
  console.log("cache after the single latest mutation fails:", qc.getQueryData(["getTodoistSettings"]));
  assert("cache restored to known prior state { A, B }", JSON.stringify(qc.getQueryData(["getTodoistSettings"])) === JSON.stringify({ taskProjectId: "A", eblastProjectId: "B" }));
}

async function scenarioD_unknownPrevious() {
  console.log("\n=== D. Latest mutation failure (previous state UNKNOWN — cache never loaded) ===");
  const qc = new FakeQueryClient(); // no initial cache value set at all
  const seqRef = { current: 0 };
  const updateSettings = makeUpdateSettings(qc, seqRef);

  let resolve1; const net1 = new Promise((r) => { resolve1 = r; });
  const req1 = saveSettings(qc, updateSettings, { taskProjectId: "C" }, net1);
  await nextTask();

  resolve1({ ok: false });
  await req1;
  console.log("invalidateQueries called instead of guessing a rollback value:", qc.invalidated === 1);
  assert("safely invalidated/refetched rather than overwriting with a guess", qc.invalidated === 1);
}

async function main() {
  await scenarioA();
  await scenarioB();
  await scenarioC();
  await scenarioD_withKnownPrevious();
  await scenarioD_unknownPrevious();
}

main();
