"$PGBIN"/psql -h 127.0.0.1 -p 55432 -U postgres -d phase1_validation << 'EOF'
\dt
SELECT 'seeding sample data' AS step;
INSERT INTO shows (name, move_in_date) VALUES ('SAMPLE VALIDATION SHOW', '2026-12-01');
INSERT INTO tasks (show_id, name, due_date, todoist_task_id) VALUES
  (currval(pg_get_serial_sequence('shows','id')), 'Sample task A', '2026-11-01', 'todoist-task-111'),
  (currval(pg_get_serial_sequence('shows','id')), 'Sample task B', '2026-11-02', NULL);
INSERT INTO eblasts (show_id, name, due_date, todoist_task_id) VALUES
  (currval(pg_get_serial_sequence('shows','id')), 'Sample eblast A', '2026-11-03', 'todoist-eblast-222');
-- Seed todoist_orphans with a mix: a duplicate pair (to test DISTINCT) and distinct entries.
INSERT INTO todoist_orphans (todoist_task_id, item_type) VALUES
  ('todoist-orphan-A', 'task'),
  ('todoist-orphan-A', 'task'),   -- deliberate duplicate, tests the DISTINCT dedupe
  ('todoist-orphan-B', 'eblast');
SELECT * FROM todoist_orphans;
EOF

PGBIN=/nix/store/bgwr5i8jf8jpg75rr53rz3fqv5k8yrwp-postgresql-16.10/bin
"$PGBIN"/psql -h 127.0.0.1 -p 55432 -U postgres -d phase1_validation << 'EOF'
SELECT 'ALL TABLES AFTER 0008' AS section;
\dt
SELECT 'NEW TABLES PRESENT?' AS section;
SELECT table_name FROM information_schema.tables
WHERE table_schema='public' AND table_name IN ('todoist_settings','todoist_sync_events','todoist_webhook_events','todoist_orphans')
ORDER BY table_name;
SELECT 'INDEXES ON NEW TABLES' AS section;
SELECT tablename, indexname FROM pg_indexes
WHERE schemaname='public' AND tablename IN ('todoist_sync_events','todoist_webhook_events')
ORDER BY tablename, indexname;
EOF

PGBIN=/nix/store/bgwr5i8jf8jpg75rr53rz3fqv5k8yrwp-postgresql-16.10/bin
"$PGBIN"/psql -h 127.0.0.1 -p 55432 -U postgres -d phase1_validation << 'EOF'
SELECT 'shows columns' AS t, column_name, data_type FROM information_schema.columns WHERE table_schema='public' AND table_name='shows' ORDER BY ordinal_position;
SELECT 'tasks columns' AS t, column_name, data_type FROM information_schema.columns WHERE table_schema='public' AND table_name='tasks' ORDER BY ordinal_position;
SELECT 'eblasts columns' AS t, column_name, data_type FROM information_schema.columns WHERE table_schema='public' AND table_name='eblasts' ORDER BY ordinal_position;
SELECT 'todoist_orphans columns' AS t, column_name, data_type FROM information_schema.columns WHERE table_schema='public' AND table_name='todoist_orphans' ORDER BY ordinal_position;
SELECT 'row counts unchanged' AS t, (SELECT COUNT(*) FROM shows) shows, (SELECT COUNT(*) FROM tasks) tasks, (SELECT COUNT(*) FROM eblasts) eblasts, (SELECT COUNT(*) FROM todoist_orphans) orphans;
EOF

PGBIN=/nix/store/bgwr5i8jf8jpg75rr53rz3fqv5k8yrwp-postgresql-16.10/bin
"$PGBIN"/psql -h 127.0.0.1 -p 55432 -U postgres -d phase1_validation << 'EOF'
SELECT 'distinct (item_type, todoist_task_id) pairs in todoist_orphans' AS metric,
       COUNT(DISTINCT (item_type, todoist_task_id)) AS value
FROM todoist_orphans;

SELECT 'raw row count in todoist_orphans (includes the deliberate duplicate)' AS metric,
       COUNT(*) AS value
FROM todoist_orphans;

SELECT 'pending delete events copied into todoist_sync_events' AS metric,
       COUNT(*) AS value
FROM todoist_sync_events
WHERE item_id IS NULL AND operation='delete' AND reason='delete' AND status='pending';

SELECT 'the actual copied rows, for inspection' AS section;
SELECT item_type, item_id, todoist_task_id, operation, reason, status, attempt_count, next_attempt_at IS NOT NULL AS has_next_attempt_at
FROM todoist_sync_events ORDER BY id;

SELECT 'todoist_orphans left untouched (still has the duplicate)?' AS metric, COUNT(*) AS value FROM todoist_orphans;
EOF

